insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('f01', null, 9, '{"rows":[".........",".........","..OX.....",".OSOX....","..SOX....","..O.X....",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Tes pierres marquées n''ont qu''une liberté, B5 : Blanc y joue et les capture. Regarde aussi les pierres blanches qui les touchent : elles sont en atari, elles aussi."}', array['D4','B5'], 'Sauve tes pierres de coupe', 'Tes deux pierres marquées coupent Blanc, mais elles sont en atari. Sauve-les.', 'Bravo ! Tes pierres marquées sont des pierres de coupe : elles séparent les pierres blanches. Elles sont en atari (une seule liberté, B5), mais les deux pierres blanches D6-D5 aussi : leur seule liberté est D4. En D4, tu les captures, et tes pierres retrouvent des libertés. B5 marche aussi : tes pierres ont alors deux libertés, et si Blanc les attaque, tu prends D6-D5 en D4.', 700),
 ('f02', null, 9, '{"rows":["....OOXO.","....OOXOX","....O.XOX","....O.XTX","....OOO.X","......OXX","......OX.","......OXX","......OX."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue H5 et relie son groupe au mur blanc G5 : il sort de la course aux libertés. Bloque d''abord la sortie."}', array['H5'], 'Deux contre deux, une sortie', 'Course aux libertés : ton groupe G6-G9 contre le groupe blanc marqué. Chacun a 2 libertés.', 'Exact ! Dans une course aux libertés (semeai), deux groupes s''entourent et le premier qui prend toutes les libertés de l''autre gagne. Blanc a 2 libertés, J9 et H5 ; toi aussi, F7 et F6. Mais H5 est une sortie : en y jouant, Blanc se relierait au mur blanc G5. Après H5, Blanc est en atari (une seule liberté) et tu le captures en J9 au coup suivant.', 720),
 ('f03', null, 9, '{"rows":[".........",".......OO",".......OO",".......X.",".......XT",".......XO",".......XO",".......X.","........X"],"toPlay":"B","refutation":"Pas tout à fait. Après ce coup, Blanc joue J6 et relie ses pierres marquées au groupe blanc du haut : elles sont sauvées. Coupe au point de liaison."}', array['J6'], 'Coupe sur le bord droit', 'Noir joue et capture les trois pierres blanches marquées. Elles ont deux libertés : J6 et J2.', 'Bien joué ! J6 coupe les pierres marquées du groupe blanc du haut : couper, c''est jouer entre deux groupes adverses pour les séparer. Leur dernière liberté, J2, est entourée par tes pierres H2 et J1 : Blanc ne peut pas s''y allonger, ce serait un suicide. Tu les captures au coup suivant.', 740),
 ('f04', null, 9, '{"rows":[".........",".........",".........",".........","....X....",".OO......","...XX....","XO.T.X...",".XXOX...."],"toPlay":"B","refutation":"Pas tout à fait. Après E2, Blanc s''allonge en C2 : il se relie à sa pierre B2 et met en plus tes pierres B1-C1 en atari. Mets-le en atari de l''autre côté."}', array['C2'], 'Le bon côté', 'Noir joue et capture les pierres blanches marquées. Elles ont deux libertés : laquelle prendre ?', 'Bien vu ! C2 coupe les pierres marquées de la pierre blanche B2 et les met en atari (une seule liberté). Leur dernière liberté, E2, est entourée par tes pierres E3, F2 et E1 : Blanc ne peut pas s''y allonger, ce serait un suicide. En plus, C2 relie tes pierres B1-C1 et met B2 en atari.', 750),
 ('f05', null, 9, '{"rows":[".........",".........",".........",".XXX.O...","X.TO.OO..",".XXX.O...",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Après ce coup, Blanc joue E5 et relie ses pierres marquées au groupe blanc de droite : elles sont sauvées. Coupe au point de liaison."}', array['E5'], 'Coupe au centre', 'Noir joue et capture les deux pierres blanches marquées. Elles ont deux libertés : B5 et E5.', 'Exact ! E5 coupe les pierres marquées du groupe blanc de droite : couper, c''est jouer entre deux groupes adverses pour les séparer. Leur dernière liberté, B5, est entourée par tes pierres A5, B6 et B4 : Blanc ne peut pas s''y allonger, ce serait un suicide. Tu les captures au coup suivant.', 760),
 ('f06', null, 9, '{"rows":["..XT.OO..","..XTXO...","..X.X....","...X.....",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Après ce coup, Blanc joue E9 et relie ses pierres marquées à son groupe de droite : elles sont sauvées. Coupe au point de liaison."}', array['E9'], 'Coupe au bord', 'Noir joue et capture les deux pierres blanches marquées. Elles ont deux libertés : E9 et D7.', 'Bravo ! E9 coupe les pierres marquées du groupe blanc de droite : couper, c''est jouer entre deux groupes adverses pour les séparer. Il leur reste une liberté, D7, entourée par tes pierres C7, E7 et D6 : Blanc ne peut pas s''y allonger, ce serait un suicide. Tu les captures au coup suivant.', 780),
 ('f07', null, 9, '{"rows":[".XO......","XXO......",".XO......","XXO......","X.OOO....","XTX.O....","XOX.O....",".OX.O....",".OXOO...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course aux libertés et ne peut plus être capturé."}', array['B5'], 'Trois contre trois, une sortie', 'Course aux libertés : ton groupe C1-C4 et le groupe blanc marqué ont chacun 3 libertés. Joue le coup qui gagne.', 'Exact ! Dans une course aux libertés (semeai), deux groupes s''entourent et le premier qui prend toutes les libertés de l''autre gagne. Blanc a 3 libertés : A2, A1 et B5. Toi aussi : D4, D3 et D2. Mais en B5, Blanc se relierait au mur blanc C5. Bloque cette sortie d''abord : Blanc n''a plus que 2 libertés contre 3 pour toi, et tu le captures un coup avant lui.', 800),
 ('f08', null, 9, '{"rows":[".XO......","XXO......",".XO......","XXO......","X.OO.....","XTX.O....",".OX......",".OX......",".OX......"],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course et ne peut plus être capturé. Bloque d''abord la sortie."}', array['B5'], 'Bloque la sortie', 'Course aux libertés : ton groupe C1-C4 contre le groupe blanc marqué. Attention, Blanc peut rejoindre son mur.', 'Bravo ! Le groupe blanc a 4 libertés : A3, A2, A1 et B5. Mais B5 n''est pas une liberté comme les autres : en y jouant, Blanc se relierait au mur blanc C5. Dans une course aux libertés (semeai), où deux groupes s''entourent et où le premier qui prend toutes les libertés de l''autre gagne, on bloque d''abord la sortie. Après B5, Blanc a 3 libertés et toi 4 (D4, D3, D2, D1) : tu gagnes la course.', 900),
 ('f09', null, 9, '{"rows":["......OX.","......OXX","......OX.","......OXX","....OOO.X","....OOXTX","...OOOXOX","...O.XXOX","...O.X.O."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue H5 et relie son groupe au mur blanc G5 : il sort de la course aux libertés. Bloque d''abord la sortie."}', array['H5'], 'Une sortie, une liberté commune', 'Course aux libertés : ton groupe contre le groupe blanc marqué. Chacun a 3 libertés. Par où commencer ?', 'Bravo ! Dans une course aux libertés (semeai), le premier qui prend toutes les libertés de l''autre gagne. Blanc a 3 libertés : J1, sa liberté extérieure (elle n''appartient qu''à lui), G1, la liberté commune aux deux groupes, et H5, une sortie vers le mur blanc G5. Tu en as 3 aussi : E2, E1 et G1. Bloque d''abord la sortie en H5 : Blanc n''a plus que 2 libertés contre 3 pour toi. Ensuite J1, et la liberté commune G1 en dernier : tu captures Blanc un coup avant lui.', 950),
 ('f10', null, 9, '{"rows":[".XO......","XXO......",".XO......","XXO......","X.OOO....","XTXOO....","XOX.OO...",".OXX.O...",".O.X.O..."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course aux libertés. Bloque d''abord la sortie."}', array['B5'], 'La sortie et la liberté commune', 'Course aux libertés : ton groupe contre le groupe blanc marqué. Compte bien : sortie, libertés extérieures, liberté commune.', 'Superbe ! Dans une course aux libertés (semeai), le premier qui prend toutes les libertés de l''autre gagne. Blanc a 4 libertés : A2 et A1, ses libertés extérieures (elles n''appartiennent qu''à lui), C1, la liberté commune aux deux groupes, et B5, une sortie vers le mur blanc C5. Tu en as 4 aussi : D3, E2, E1 et C1. Bloque d''abord la sortie en B5. Ensuite, remplis A2 et A1 et garde C1 pour la fin : tu captures Blanc un coup avant lui.', 1000),
 ('f11', null, 9, '{"rows":[".O.X.XOO.",".OXXXX.O.","XOXOOOO..","XTXOO....","X.OOO....","XXO......",".XO......","XXO......",".XO......"],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course aux libertés. Bloque d''abord la sortie."}', array['B5'], 'L''œil et la sortie', 'Course aux libertés : ton groupe a un œil en E9, le groupe blanc marqué a une liberté de plus. Gagne la course.', 'Magnifique ! Ton groupe a un œil en E9 : un point vide entouré par tes pierres, où Blanc ne peut jouer qu''en dernier. Dans cette course aux libertés (semeai), Blanc a 4 libertés : A9, A8, C9 (commune aux deux groupes) et B5, une sortie vers le mur blanc C5. Tu en as 3 : l''œil E9, C9 et G8. Bloque d''abord la sortie en B5. Ensuite, Blanc ne peut pas jouer dans ton œil (ce serait un suicide), et s''il remplit C9, il s''enlève aussi une liberté. Tu remplis A8 et A9, puis tu le captures.', 1250)
